import { advance, type Cursor, expect as expectChar, parseFail, peek } from '@/parse/cursor'
import { parseItemInternal } from '@/parse/item'
import { parseParameters } from '@/parse/parameters'
import type { InnerList, Item } from '@/types'
import { EOF, HTAB, LPAREN, RPAREN, SP } from '@/util/chars'

/**
 * Parses an Inner List at the cursor.
 *
 * Members are separated by one or more ASCII spaces. Tab characters are not
 * permitted between members. Trailing whitespace before `)` is allowed.
 *
 * @param cursor The cursor positioned at the opening `(`. Advanced past the
 *   matching `)` and any parameters that follow.
 * @returns An InnerList with the parsed items and any trailing parameters.
 * @throws ParseError if the inner list is unterminated, contains a tab, or
 *   contains an unexpected character after a member.
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.1.2 | RFC 9651 section 4.2.1.2}
 */
export function parseInnerList(cursor: Cursor): InnerList {
  expectChar(cursor, LPAREN, "expected '('")
  const items: Item[] = []

  while (true) {
    // Skip leading/inter-item space. Multiple spaces are allowed, tabs are not.
    while (peek(cursor) === SP) {
      advance(cursor)
    }

    const charCode = peek(cursor)
    if (charCode === RPAREN) {
      advance(cursor)
      const parameters = parseParameters(cursor)
      return { type: 'innerList', value: items, parameters }
    }
    if (charCode === EOF) {
      parseFail(cursor, 'unterminated inner list')
    }
    if (charCode === HTAB) {
      parseFail(cursor, 'tab not allowed inside inner list')
    }

    items.push(parseItemInternal(cursor))

    // After parsing an item the next character must be SP, `)`, or EOF
    // (the EOF case is caught as "unterminated" on the next iteration).
    const next = peek(cursor)
    if (next !== SP && next !== RPAREN && next !== EOF) {
      parseFail(cursor, "expected space or ')' after inner list item")
    }
  }
}
