import { SerializeError } from '@/errors'
import { BACKSLASH, QUOTE, SP, TILDE } from '@/util/chars'

/**
 * Serializes a String.
 *
 * Allowed characters are printable ASCII ({@link SP} through {@link TILDE}).
 * Embedded backslash and double-quote characters are escaped with a leading
 * backslash; any other character outside the printable range is rejected.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.6 | RFC 9651 section 4.1.6}
 */
export function serializeString(value: string): string {
  let output = '"'
  for (let index = 0; index < value.length; index += 1) {
    const charCode = value.charCodeAt(index)
    if (charCode < SP || charCode > TILDE) {
      throw new SerializeError('string contains non-printable or non-ASCII character', { code: 'string-characters' })
    }
    if (charCode === QUOTE || charCode === BACKSLASH) {
      output += '\\'
    }
    output += value[index]
  }
  output += '"'
  return output
}
