import { serializeDictionaryInternal } from '@/serialize/dictionary'
import { serializeItemInternal } from '@/serialize/item'
import { serializeListInternal } from '@/serialize/list'
import type { Dictionary, Item, List } from '@/types'

/**
 * Serializes an Item to its canonical RFC 9651 wire form.
 *
 * @param item An Item, typically produced by the construction helpers
 *   ({@link itemConstruct}, {@link integer}, {@link token}, and so on) or
 *   round-tripped from {@link parseItem}.
 * @returns The header value string.
 * @throws SerializeError if the value cannot be represented per RFC 9651
 *   (for example an Integer outside the spec's range, or a String with
 *   non-ASCII characters).
 */
export function serializeItem(item: Item): string {
  return serializeItemInternal(item)
}

/**
 * Serializes a List to its canonical RFC 9651 wire form.
 *
 * @param list A read-only array of List entries.
 * @returns The header value string. An empty list produces an empty string.
 * @throws SerializeError if any entry value violates RFC 9651.
 */
export function serializeList(list: List): string {
  return serializeListInternal(list)
}

/**
 * Serializes a Dictionary to its canonical RFC 9651 wire form.
 *
 * Entries whose value is a Boolean `true` Item without parameters are emitted
 * in short form (just the key), matching the canonical encoding in the spec.
 *
 * @param dictionary A `Map` of entries. Iteration order determines output order.
 * @returns The header value string. An empty dictionary produces an empty string.
 * @throws SerializeError if any key violates the Key grammar or any value
 *   violates RFC 9651.
 */
export function serializeDictionary(dictionary: Dictionary): string {
  return serializeDictionaryInternal(dictionary)
}
