import { ParseError } from '@/errors'
import { advance, type Cursor, expect as expectChar, parseFail, peek } from '@/parse/cursor'
import { decodeBase64 } from '@/util/base64'
import { COLON, EOF } from '@/util/chars'

/**
 * Parses a Byte Sequence at the cursor.
 *
 * Wire form: `:base64:`. The standard base64 alphabet is required and
 * padding is mandatory. The encoded segment between the colons is sliced in
 * one shot and handed to {@link decodeBase64}; base64 errors are wrapped as
 * `ParseError` so callers see a uniform error type.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.7 | RFC 9651 section 4.2.7}
 */
export function parseByteSequence(cursor: Cursor): Uint8Array {
  expectChar(cursor, COLON, "expected ':'")

  const encodedStart = cursor.offset
  while (peek(cursor) !== COLON) {
    if (peek(cursor) === EOF) {
      parseFail(cursor, 'unterminated byte sequence')
    }
    advance(cursor)
  }
  const encoded = cursor.input.slice(encodedStart, cursor.offset)
  advance(cursor) // consume the closing colon

  try {
    return decodeBase64(encoded)
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : 'invalid base64'
    throw new ParseError(message, {
      offset: encodedStart,
      input: cursor.input,
    })
  }
}
