import { parseBareItem } from '@/parse/bare-item'
import type { Cursor } from '@/parse/cursor'
import { parseParameters } from '@/parse/parameters'
import type { Item } from '@/types'

/**
 * Parses an Item at the cursor (internal helper).
 *
 * The top-level `parseItem` wrapper handles leading and trailing whitespace
 * and end-of-input checks. This helper assumes the cursor is at the start
 * of the Item content.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.3 | RFC 9651 section 4.2.3}
 */
export function parseItemInternal(cursor: Cursor): Item {
  const value = parseBareItem(cursor)
  const parameters = parseParameters(cursor)
  return { type: 'item', value, parameters }
}
