import { serializeInnerList } from '@/serialize/inner-list'
import { serializeItemInternal } from '@/serialize/item'
import type { List, ListEntry } from '@/types'

/**
 * Serializes a List (internal helper).
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.1 | RFC 9651 section 4.1.1}
 */
export function serializeListInternal(list: List): string {
  if (list.length === 0) {
    return ''
  }
  return list.map(serializeListEntry).join(', ')
}

/**
 * Serializes a single list entry: dispatches on `type` to either an Item
 * or an InnerList.
 */
export function serializeListEntry(entry: ListEntry): string {
  if (entry.type === 'innerList') {
    return serializeInnerList(entry)
  }
  return serializeItemInternal(entry)
}
