import { serializeBareItem } from '@/serialize/bare-item'
import { serializeKey } from '@/serialize/key'
import type { Parameters } from '@/types'

/**
 * Serializes Parameters.
 *
 * Boolean true is omitted (canonical short form). All other values are emitted
 * with `=value`.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.1.2 | RFC 9651 section 4.1.1.2}
 */
export function serializeParameters(parameters: Parameters): string {
  if (parameters.size === 0) {
    return ''
  }
  const parts: string[] = []
  for (const [name, value] of parameters) {
    let part = `;${serializeKey(name)}`
    if (!(value.type === 'boolean' && value.value === true)) {
      part += `=${serializeBareItem(value)}`
    }
    parts.push(part)
  }
  return parts.join('')
}
