const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

/** ASCII code for the base64 padding character `=`. */
const PADDING_CHAR_CODE = 0x3d

/** First non-ASCII code point. Used to bound the decode table. */
const ASCII_RANGE = 128

/** Sentinel used in the decode table for character codes that are not valid base64 digits. */
const NOT_A_BASE64_DIGIT = -1

/**
 * Lookup table mapping ASCII codes to their base64 alphabet index.
 *
 * Indexing the table with a non-base64 ASCII code returns
 * {@link NOT_A_BASE64_DIGIT}; indices outside the ASCII range are not
 * defined and must be guarded by callers.
 */
const DECODE_TABLE = (() => {
  const table = new Int8Array(ASCII_RANGE).fill(NOT_A_BASE64_DIGIT)
  for (let alphabetIndex = 0; alphabetIndex < ALPHABET.length; alphabetIndex += 1) {
    table[ALPHABET.charCodeAt(alphabetIndex)] = alphabetIndex
  }
  return table
})()

/**
 * Decodes a standard base64 string with required padding.
 *
 * Throws if the input length is not a multiple of 4, contains characters
 * outside the standard base64 alphabet, or has invalid padding placement.
 */
export function decodeBase64(input: string): Uint8Array {
  if (input.length === 0) {
    return new Uint8Array(0)
  }
  if (input.length % 4 !== 0) {
    throw new Error('base64 input length must be a multiple of 4')
  }

  const paddingCount = countTrailingPadding(input)
  if (paddingCount > 2) {
    throw new Error('base64 input has too much padding')
  }

  const outputLength = (input.length / 4) * 3 - paddingCount
  const output = new Uint8Array(outputLength)
  const lastQuadStart = input.length - 4
  let writeIndex = 0

  for (let readIndex = 0; readIndex < input.length; readIndex += 4) {
    const isLastQuad = readIndex === lastQuadStart
    const sextet0 = decodeAlphabetCharacter(input, readIndex)
    const sextet1 = decodeAlphabetCharacter(input, readIndex + 1)
    const sextet2 = isLastQuad && paddingCount >= 2 ? NOT_A_BASE64_DIGIT : decodeAlphabetCharacter(input, readIndex + 2)
    const sextet3 = isLastQuad && paddingCount >= 1 ? NOT_A_BASE64_DIGIT : decodeAlphabetCharacter(input, readIndex + 3)

    output[writeIndex] = (sextet0 << 2) | (sextet1 >> 4)
    writeIndex += 1
    if (sextet2 !== NOT_A_BASE64_DIGIT) {
      output[writeIndex] = ((sextet1 & 0x0f) << 4) | (sextet2 >> 2)
      writeIndex += 1
      if (sextet3 !== NOT_A_BASE64_DIGIT) {
        output[writeIndex] = ((sextet2 & 0x03) << 6) | sextet3
        writeIndex += 1
      }
    }
  }

  return output
}

function countTrailingPadding(input: string): number {
  let paddingCount = 0
  if (input.charCodeAt(input.length - 1) === PADDING_CHAR_CODE) {
    paddingCount += 1
  }
  if (input.charCodeAt(input.length - 2) === PADDING_CHAR_CODE) {
    paddingCount += 1
  }
  return paddingCount
}

function decodeAlphabetCharacter(input: string, index: number): number {
  const charCode = input.charCodeAt(index)
  if (charCode >= ASCII_RANGE) {
    throw new Error('base64 input contains non-ASCII')
  }
  const sextet = DECODE_TABLE[charCode]
  if (sextet === undefined || sextet === NOT_A_BASE64_DIGIT) {
    throw new Error('base64 input contains invalid character')
  }
  return sextet
}

/**
 * Encodes bytes as a standard base64 string with required padding.
 */
export function encodeBase64(bytes: Uint8Array): string {
  if (bytes.length === 0) {
    return ''
  }

  let output = ''
  let readIndex = 0
  while (readIndex + 3 <= bytes.length) {
    const byte0 = bytes[readIndex]!
    const byte1 = bytes[readIndex + 1]!
    const byte2 = bytes[readIndex + 2]!
    output +=
      ALPHABET[byte0 >> 2]! +
      ALPHABET[((byte0 & 0x03) << 4) | (byte1 >> 4)]! +
      ALPHABET[((byte1 & 0x0f) << 2) | (byte2 >> 6)]! +
      ALPHABET[byte2 & 0x3f]!
    readIndex += 3
  }

  const remainingBytes = bytes.length - readIndex
  if (remainingBytes === 1) {
    const byte0 = bytes[readIndex]!
    output += ALPHABET[byte0 >> 2]! + ALPHABET[(byte0 & 0x03) << 4]! + '=='
  } else if (remainingBytes === 2) {
    const byte0 = bytes[readIndex]!
    const byte1 = bytes[readIndex + 1]!
    output +=
      ALPHABET[byte0 >> 2]! + ALPHABET[((byte0 & 0x03) << 4) | (byte1 >> 4)]! + ALPHABET[(byte1 & 0x0f) << 2]! + '='
  }
  return output
}
