import { ASTERISK, DIGIT_NINE, DIGIT_ZERO, LOWER_A, LOWER_Z, UPPER_A, UPPER_Z } from '@/util/chars'

/** ASCII lowercase letter, `a` through `z`. */
export function isLowerCaseAlpha(charCode: number): boolean {
  return charCode >= LOWER_A && charCode <= LOWER_Z
}

/** ASCII uppercase letter, `A` through `Z`. */
export function isUpperCaseAlpha(charCode: number): boolean {
  return charCode >= UPPER_A && charCode <= UPPER_Z
}

/** ASCII digit, `0` through `9`. */
export function isDigit(charCode: number): boolean {
  return charCode >= DIGIT_ZERO && charCode <= DIGIT_NINE
}

/**
 * First character of a Token: `ALPHA` or `*`.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-3.3.4 | RFC 9651 section 3.3.4}
 */
export function isTokenStart(charCode: number): boolean {
  return isLowerCaseAlpha(charCode) || isUpperCaseAlpha(charCode) || charCode === ASTERISK
}

/**
 * Subsequent Token character: `tchar` (RFC 7230) plus `:` and `/`.
 *
 * `tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" / "-" / "." /
 *          "^" / "_" / "`" / "|" / "~" / DIGIT / ALPHA`
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-3.3.4 | RFC 9651 section 3.3.4}
 */
export function isTokenChar(charCode: number): boolean {
  if (isLowerCaseAlpha(charCode) || isUpperCaseAlpha(charCode) || isDigit(charCode)) {
    return true
  }
  switch (charCode) {
    case 0x21: // !
    case 0x23: // #
    case 0x24: // $
    case 0x25: // %
    case 0x26: // &
    case 0x27: // '
    case 0x2a: // *
    case 0x2b: // +
    case 0x2d: // -
    case 0x2e: // .
    case 0x2f: // /
    case 0x3a: // :
    case 0x5e: // ^
    case 0x5f: // _
    case 0x60: // `
    case 0x7c: // |
    case 0x7e: // ~
      return true
    default:
      return false
  }
}

/**
 * First character of a Key: `lcalpha` or `*`.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-3.1.2 | RFC 9651 section 3.1.2}
 */
export function isKeyStart(charCode: number): boolean {
  return isLowerCaseAlpha(charCode) || charCode === ASTERISK
}

/**
 * Subsequent Key character: `lcalpha` / DIGIT / `_` / `-` / `.` / `*`.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-3.1.2 | RFC 9651 section 3.1.2}
 */
export function isKeyChar(charCode: number): boolean {
  if (isLowerCaseAlpha(charCode) || isDigit(charCode)) {
    return true
  }
  switch (charCode) {
    case 0x2a: // *
    case 0x2d: // -
    case 0x2e: // .
    case 0x5f: // _
      return true
    default:
      return false
  }
}
