import { advance, type Cursor, expect as expectChar, parseFail, peek } from '@/parse/cursor'
import { isDigit, isLowerCaseAlpha } from '@/util/ascii'
import { DIGIT_ZERO, EOF, LOWER_A, LOWER_F, PERCENT, QUOTE, SP, TILDE } from '@/util/chars'

/**
 * Parses a Display String at the cursor.
 *
 * The wire form is `%"<percent-encoded-utf-8>"`. Bytes outside the printable
 * ASCII range, plus `%` and `"` themselves, must appear as `%xx` (lowercase
 * hex). The decoded byte sequence is then validated as UTF-8 in strict mode.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.10 | RFC 9651 section 4.2.10}
 */
export function parseDisplayString(cursor: Cursor): string {
  expectChar(cursor, PERCENT, "expected '%'")
  expectChar(cursor, QUOTE, "expected '\"'")

  const bytes: number[] = []
  while (true) {
    const charCode = peek(cursor)
    if (charCode === EOF) {
      parseFail(cursor, 'unterminated display string')
    }
    if (charCode === QUOTE) {
      advance(cursor)
      break
    }
    if (charCode === PERCENT) {
      advance(cursor)
      const high = readHexDigit(cursor)
      const low = readHexDigit(cursor)
      bytes.push((high << 4) | low)
      continue
    }
    if (charCode < SP || charCode > TILDE) {
      parseFail(cursor, 'display string contains unencoded non-printable')
    }
    bytes.push(charCode)
    advance(cursor)
  }

  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(new Uint8Array(bytes))
  } catch {
    parseFail(cursor, 'display string contains invalid UTF-8')
  }
}

function readHexDigit(cursor: Cursor): number {
  const charCode = peek(cursor)
  if (isDigit(charCode)) {
    advance(cursor)
    return charCode - DIGIT_ZERO
  }
  if (isLowerCaseAlpha(charCode) && charCode <= LOWER_F) {
    advance(cursor)
    return charCode - LOWER_A + 10
  }
  parseFail(cursor, 'expected lowercase hex digit')
}
