import { parseBoolean } from '@/parse/boolean'
import { parseByteSequence } from '@/parse/byte-sequence'
import { type Cursor, parseFail, peek } from '@/parse/cursor'
import { parseDate } from '@/parse/date'
import { parseDisplayString } from '@/parse/display-string'
import { parseIntegerOrDecimal } from '@/parse/number'
import { parseString } from '@/parse/string'
import { parseToken } from '@/parse/token'
import type { BareItem } from '@/types'
import { isDigit, isTokenStart } from '@/util/ascii'
import { AT_SIGN, COLON, HYPHEN_MINUS, PERCENT, QUESTION_MARK, QUOTE } from '@/util/chars'

/**
 * Parses a Bare Item at the cursor by dispatching on the leading character.
 *
 * Each branch consumes the prefix that identifies its type, then defers to
 * the corresponding leaf parser. Numeric literals start with a digit or `-`,
 * everything else starts with a single distinguishing character.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.3.1 | RFC 9651 section 4.2.3.1}
 */
export function parseBareItem(cursor: Cursor): BareItem {
  const charCode = peek(cursor)

  if (isDigit(charCode) || charCode === HYPHEN_MINUS) {
    return parseIntegerOrDecimal(cursor)
  }
  if (charCode === QUOTE) {
    return { type: 'string', value: parseString(cursor) }
  }
  if (charCode === COLON) {
    return { type: 'byteSequence', value: parseByteSequence(cursor) }
  }
  if (charCode === QUESTION_MARK) {
    return { type: 'boolean', value: parseBoolean(cursor) }
  }
  if (charCode === AT_SIGN) {
    return { type: 'date', value: parseDate(cursor) }
  }
  if (charCode === PERCENT) {
    return { type: 'displayString', value: parseDisplayString(cursor) }
  }
  if (isTokenStart(charCode)) {
    return { type: 'token', value: parseToken(cursor) }
  }
  parseFail(cursor, 'expected bare item')
}
