import { SerializeError } from '@/errors'
import { isTokenChar, isTokenStart } from '@/util/ascii'

/**
 * Serializes a Token, validating its grammar.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.7 | RFC 9651 section 4.1.7}
 */
export function serializeToken(value: string): string {
  if (value.length === 0) {
    throw new SerializeError('token must not be empty', {
      code: 'token-grammar',
    })
  }
  if (!isTokenStart(value.charCodeAt(0))) {
    throw new SerializeError("token must start with ALPHA or '*'", {
      code: 'token-grammar',
    })
  }
  for (let index = 1; index < value.length; index += 1) {
    if (!isTokenChar(value.charCodeAt(index))) {
      throw new SerializeError('token contains invalid character', {
        code: 'token-grammar',
      })
    }
  }
  return value
}
