import { ParseError } from '@/errors'
import { advance, type Cursor, parseFail, peek } from '@/parse/cursor'
import { isDigit } from '@/util/ascii'
import { DOT, HYPHEN_MINUS } from '@/util/chars'

const INTEGER_MAX_DIGITS = 15
const DECIMAL_INTEGER_MAX_DIGITS = 12
const DECIMAL_FRACTIONAL_MAX_DIGITS = 3

/**
 * Parses an Integer or Decimal at the cursor.
 *
 * The discriminant in the result is determined by whether the input contained
 * a decimal point, never by whether the resulting JS number happens to be
 * integer-valued. This preserves round-trip fidelity for inputs like `5.0`.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.4 | RFC 9651 section 4.2.4}
 */
export function parseIntegerOrDecimal(
  cursor: Cursor
): { type: 'integer'; value: number } | { type: 'decimal'; value: number } {
  const startOffset = cursor.offset

  let signMultiplier = 1
  if (peek(cursor) === HYPHEN_MINUS) {
    advance(cursor)
    signMultiplier = -1
  }

  if (!isDigit(peek(cursor))) {
    parseFail(cursor, 'expected digit')
  }

  const integerStart = cursor.offset
  while (isDigit(peek(cursor))) {
    advance(cursor)
    if (cursor.offset - integerStart > INTEGER_MAX_DIGITS) {
      throw failAt(cursor, startOffset, 'integer too long')
    }
  }
  const integerDigits = cursor.input.slice(integerStart, cursor.offset)

  if (peek(cursor) !== DOT) {
    // Integer path. Normalise -0 to 0; RFC 9651 has no negative zero.
    const value = signMultiplier * Number(integerDigits)
    return { type: 'integer', value: value === 0 ? 0 : value }
  }

  // Decimal path. The integer portion is bounded more tightly.
  if (integerDigits.length > DECIMAL_INTEGER_MAX_DIGITS) {
    throw failAt(cursor, startOffset, 'decimal integer part too long')
  }
  advance(cursor) // consume "."

  const fractionalStart = cursor.offset
  while (isDigit(peek(cursor))) {
    advance(cursor)
    if (cursor.offset - fractionalStart > DECIMAL_FRACTIONAL_MAX_DIGITS) {
      throw failAt(cursor, startOffset, 'decimal fractional part too long')
    }
  }
  if (cursor.offset === fractionalStart) {
    parseFail(cursor, 'decimal must have at least one fractional digit')
  }

  const fractionalDigits = cursor.input.slice(fractionalStart, cursor.offset)
  const value = signMultiplier * Number(`${integerDigits}.${fractionalDigits}`)
  return { type: 'decimal', value }
}

/**
 * Builds a {@link ParseError} that points at the start of the numeric literal
 * rather than the character that triggered the failure. This keeps the
 * reported offset on the bad token, not on the position past it.
 */
function failAt(cursor: Cursor, offset: number, message: string): ParseError {
  return new ParseError(message, { offset, input: cursor.input })
}
