import { advance, type Cursor, parseFail, peek } from '@/parse/cursor'
import { isTokenChar, isTokenStart } from '@/util/ascii'

/**
 * Parses a Token at the cursor.
 *
 * The Token grammar requires the first character to be `ALPHA` or `*`, with
 * subsequent characters drawn from `tchar` plus `:` and `/`. The parser stops
 * at the first character that does not match `isTokenChar`.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.6 | RFC 9651 section 4.2.6}
 */
export function parseToken(cursor: Cursor): string {
  if (!isTokenStart(peek(cursor))) {
    parseFail(cursor, 'expected token start')
  }

  const startOffset = cursor.offset
  advance(cursor) // consume the validated start character
  while (isTokenChar(peek(cursor))) {
    advance(cursor)
  }
  return cursor.input.slice(startOffset, cursor.offset)
}
