import { ParseError } from '@/errors'
import { parseDictionary, parseList } from '@/parse'
import type { BareItemValueOf, FieldSchema, Schema } from '@/schema/types'
import type { BareItemKind, InnerList, Item, ParseResult } from '@/types'

class SchemaError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'SchemaError'
  }
}

function safeRun<T>(action: () => T): ParseResult<T> {
  try {
    return { ok: true, value: action() }
  } catch (error) {
    if (error instanceof ParseError) {
      return { ok: false, error }
    }
    if (error instanceof SchemaError) {
      return {
        ok: false,
        error: new ParseError(error.message, { offset: 0, input: '' }),
      }
    }
    throw error
  }
}

function expectItem(entry: unknown): Item {
  if (typeof entry !== 'object' || entry === null || (entry as { type?: string }).type !== 'item') {
    throw new SchemaError('expected an item, got something else')
  }
  return entry as Item
}

function expectInnerList(entry: unknown): InnerList {
  if (typeof entry !== 'object' || entry === null || (entry as { type?: string }).type !== 'innerList') {
    throw new SchemaError('expected an inner list, got something else')
  }
  return entry as InnerList
}

/**
 * Builds a field schema for a single Bare Item of the given kind.
 *
 * The result extracts the underlying JS value (for instance a `number` for
 * `"integer"` or a `Uint8Array` for `"byteSequence"`) and rejects entries of
 * any other type.
 *
 * @param kind The expected `BareItem` discriminant.
 * @returns A field schema usable inside {@link dictionary} or as the inner
 *   schema of {@link list}.
 *
 * @example
 * ```ts
 * const ageSchema = item("integer"); // FieldSchema<number>
 * ```
 */
export function item<TKind extends BareItemKind>(kind: TKind): FieldSchema<BareItemValueOf<TKind>> {
  return {
    extract: (entry) => {
      const itemEntry = expectItem(entry)
      if (itemEntry.value.type !== kind) {
        throw new SchemaError(`expected ${kind}, got ${itemEntry.value.type}`)
      }
      return itemEntry.value.value as BareItemValueOf<TKind>
    },
    optional: false,
  }
}

/**
 * Builds a list-valued schema where every member is shaped by `itemSchema`.
 *
 * The returned object satisfies both `Schema<ReadonlyArray<TItem>>` (use the
 * `parse` and `safeParse` methods to consume a top-level List header) and
 * `FieldSchema<ReadonlyArray<TItem>>` (so the same schema can serve as a
 * dictionary field whose value is an Inner List).
 *
 * @param itemSchema The schema applied to each list member.
 * @returns A combined Schema and FieldSchema.
 *
 * @example
 * ```ts
 * const tagsSchema = list(item("token"));
 * tagsSchema.parse("foo, bar, baz"); // ["foo", "bar", "baz"]
 * ```
 */
export function list<TItem>(
  itemSchema: FieldSchema<TItem>
): Schema<ReadonlyArray<TItem>> & FieldSchema<ReadonlyArray<TItem>> {
  const extract = (entry: unknown): ReadonlyArray<TItem> => {
    const inner = expectInnerList(entry)
    return inner.value.map((member) => itemSchema.extract(member))
  }
  const parse = (input: string): ReadonlyArray<TItem> => {
    const parsed = parseList(input)
    return parsed.map((entry) => itemSchema.extract(entry))
  }
  return {
    parse,
    safeParse: (input) => safeRun(() => parse(input)),
    extract,
    optional: false,
  }
}

/**
 * Builds a Dictionary schema whose output is a typed object.
 *
 * Each property of `fields` declares one named entry the schema should look
 * for in the parsed Dictionary. The resulting object's keys mirror the field
 * map exactly, and the value at each key is `T | undefined` (or `T` if the
 * field uses {@link withDefault}).
 *
 * @param fields A record mapping output keys to field schemas.
 * @returns A Schema that returns a typed object on `parse`.
 *
 * @example
 * ```ts
 * const cacheControl = dictionary({
 *   "max-age": withDefault(item("integer"), 0),
 *   private: withDefault(item("boolean"), false),
 * });
 * const result = cacheControl.parse("max-age=600, private");
 * result["max-age"]; // 600
 * result.private;    // true
 * ```
 */
export function dictionary<TFields extends Record<string, FieldSchema<unknown>>>(
  fields: TFields
): Schema<{
  [K in keyof TFields]: TFields[K] extends FieldSchema<infer U> ? U | undefined : never
}> {
  type Output = {
    [K in keyof TFields]: TFields[K] extends FieldSchema<infer U> ? U | undefined : never
  }
  const parse = (input: string): Output => {
    const parsed = parseDictionary(input)
    const output = {} as Output
    for (const fieldName of Object.keys(fields) as Array<keyof TFields>) {
      const fieldSchema = fields[fieldName]!
      const dictionaryKey = String(fieldName)
      const entry = parsed.get(dictionaryKey)
      if (entry === undefined) {
        if (fieldSchema.defaultValue !== undefined) {
          output[fieldName] = fieldSchema.defaultValue as Output[typeof fieldName]
        } else {
          output[fieldName] = undefined as Output[typeof fieldName]
        }
        continue
      }
      output[fieldName] = fieldSchema.extract(entry) as Output[typeof fieldName]
    }
    return output
  }
  return {
    parse,
    safeParse: (input) => safeRun(() => parse(input)),
  }
}

/**
 * Widens a field schema's output type to include `undefined`.
 *
 * Use this for Dictionary entries that may be absent. The default behaviour
 * of {@link dictionary} already produces `T | undefined` for every field, so
 * `optional` is mainly useful when a field schema is reused in contexts that
 * would otherwise require a value.
 *
 * @param field The field schema to widen.
 * @returns A new field schema whose output type is `T | undefined`.
 */
export function optional<T>(field: FieldSchema<T>): FieldSchema<T | undefined> {
  return { ...field, optional: true } as FieldSchema<T | undefined>
}

/**
 * Provides a fallback value used when the corresponding entry is absent
 * from the parsed input.
 *
 * @param field The field schema to wrap.
 * @param defaultValue The value to substitute when the entry is missing.
 * @returns A new field schema whose output type is `T` (no `undefined`).
 *
 * @example
 * ```ts
 * const schema = dictionary({ count: withDefault(item("integer"), 0) });
 * schema.parse("").count; // 0
 * ```
 */
export function withDefault<T>(field: FieldSchema<T>, defaultValue: T): FieldSchema<T> {
  return { ...field, defaultValue }
}

/**
 * Adds a runtime predicate to a field schema. The predicate runs after the
 * value has been extracted from the parsed entry and rejects values that
 * fall outside the desired set.
 *
 * @param field The field schema to constrain.
 * @param predicate Returns `true` for accepted values.
 * @param message Optional error message used when the predicate rejects.
 * @returns A new field schema with the same output type and an extra check.
 *
 * @example
 * ```ts
 * const positive = refine(item("integer"), (n) => n > 0, "must be positive");
 * ```
 */
export function refine<T>(
  field: FieldSchema<T>,
  predicate: (value: T) => boolean,
  message = 'value did not match refinement'
): FieldSchema<T> {
  const wrappedExtract = (entry: unknown): T => {
    const value = field.extract(entry) as T
    if (!predicate(value)) {
      throw new SchemaError(message)
    }
    return value
  }
  return { ...field, extract: wrappedExtract } as FieldSchema<T>
}
