import { serializeKey } from '@/serialize/key'
import { serializeListEntry } from '@/serialize/list'
import { serializeParameters } from '@/serialize/parameters'
import type { Dictionary } from '@/types'

/**
 * Serializes a Dictionary (internal helper).
 *
 * For an entry whose value is a boolean-true Item, emit just the key (canonical
 * short form). Entry-level parameters follow the key. Otherwise emit `key=value`.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.2 | RFC 9651 section 4.1.2}
 */
export function serializeDictionaryInternal(dictionary: Dictionary): string {
  if (dictionary.size === 0) {
    return ''
  }
  const parts: string[] = []
  for (const [name, entry] of dictionary) {
    if (entry.type === 'item' && entry.value.type === 'boolean' && entry.value.value === true) {
      parts.push(`${serializeKey(name)}${serializeParameters(entry.parameters)}`)
    } else {
      parts.push(`${serializeKey(name)}=${serializeListEntry(entry)}`)
    }
  }
  return parts.join(', ')
}
