import { serializeBareItem } from '@/serialize/bare-item'
import { serializeParameters } from '@/serialize/parameters'
import type { Item } from '@/types'

/**
 * Serializes an Item (internal helper).
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.3 | RFC 9651 section 4.1.3}
 */
export function serializeItemInternal(item: Item): string {
  return serializeBareItem(item.value) + serializeParameters(item.parameters)
}
