import { parseBareItem } from '@/parse/bare-item'
import { advance, type Cursor, peek } from '@/parse/cursor'
import { parseKey } from '@/parse/key'
import type { BareItem, Parameters } from '@/types'
import { EQUALS, SEMICOLON, SP } from '@/util/chars'

/**
 * Parses a Parameters block at the cursor.
 *
 * Returns an empty Map when the next character is not `;`. For repeated
 * keys, the value of the last occurrence wins, but the key keeps the
 * position of its first occurrence (`Map.set` preserves insertion order).
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.3.2 | RFC 9651 section 4.2.3.2}
 */
export function parseParameters(cursor: Cursor): Parameters {
  const parameters = new Map<string, BareItem>()
  while (peek(cursor) === SEMICOLON) {
    advance(cursor)
    while (peek(cursor) === SP) {
      advance(cursor)
    }
    const name = parseKey(cursor)
    parameters.set(name, parseParameterValue(cursor))
  }
  return parameters
}

/**
 * Parses the optional `=value` portion of a parameter. A bare key with no
 * `=` represents a Boolean `true`.
 */
function parseParameterValue(cursor: Cursor): BareItem {
  if (peek(cursor) === EQUALS) {
    advance(cursor)
    return parseBareItem(cursor)
  }
  return { type: 'boolean', value: true }
}
