import { ParseError } from '@/errors'
import { type Cursor, parseFail, peek, skipSP } from '@/parse/cursor'
import { parseDictionaryInternal } from '@/parse/dictionary'
import { parseItemInternal } from '@/parse/item'
import { parseListInternal } from '@/parse/list'
import type { Dictionary, Item, List, ParseResult } from '@/types'
import { EOF } from '@/util/chars'

function makeCursor(input: string): Cursor {
  return { input, offset: 0 }
}

function ensureExhausted(cursor: Cursor): void {
  skipSP(cursor)
  if (peek(cursor) !== EOF) {
    parseFail(cursor, 'trailing data after value')
  }
}

/**
 * Parses a Structured Field Item from a header value string.
 *
 * Use this when the field is defined as a single Item (per its specification),
 * for example a Token with optional parameters.
 *
 * @param input The raw header value. Leading and trailing ASCII spaces are
 *   tolerated; any other content after the Item produces an error.
 * @returns The parsed Item, including its bare value and parameters.
 * @throws ParseError when the input is not a valid Item or carries trailing data.
 *
 * @example
 * ```ts
 * const accept = parseItem("application/json;q=0.9");
 * accept.value; // { type: "token", value: "application/json" }
 * accept.parameters.get("q"); // { type: "decimal", value: 0.9 }
 * ```
 */
export function parseItem(input: string): Item {
  const cursor = makeCursor(input)
  skipSP(cursor)
  const result = parseItemInternal(cursor)
  ensureExhausted(cursor)
  return result
}

/**
 * Parses a Structured Field List from a header value string.
 *
 * Use this when the field is defined as a List, where members may be Items
 * or Inner Lists separated by commas.
 *
 * @param input The raw header value.
 * @returns A read-only array of List entries. An empty input returns an empty array.
 * @throws ParseError on any malformed entry, missing comma, or trailing comma.
 *
 * @example
 * ```ts
 * const accept = parseList("text/html, application/json;q=0.9");
 * accept.length; // 2
 * ```
 */
export function parseList(input: string): List {
  const cursor = makeCursor(input)
  skipSP(cursor)
  const result = parseListInternal(cursor)
  ensureExhausted(cursor)
  return result
}

/**
 * Parses a Structured Field Dictionary from a header value string.
 *
 * Use this when the field is defined as a Dictionary, where each entry has
 * a key and either an Item value, an Inner List value, or no value at all
 * (which represents a Boolean true).
 *
 * @param input The raw header value.
 * @returns A `Map` of entries in insertion order. An empty input returns an empty map.
 * @throws ParseError on any malformed key, missing comma, or trailing comma.
 *
 * @example
 * ```ts
 * const cc = parseDictionary("max-age=600, private, must-revalidate");
 * cc.has("private"); // true
 * ```
 */
export function parseDictionary(input: string): Dictionary {
  const cursor = makeCursor(input)
  skipSP(cursor)
  const result = parseDictionaryInternal(cursor)
  ensureExhausted(cursor)
  return result
}

function safeRun<T>(action: () => T): ParseResult<T> {
  try {
    return { ok: true, value: action() }
  } catch (error) {
    if (error instanceof ParseError) return { ok: false, error }
    throw error
  }
}

/**
 * Non-throwing variant of {@link parseItem}.
 *
 * @param input The raw header value.
 * @returns A discriminated `ParseResult`. On failure, `result.error` is the
 *   `ParseError` that {@link parseItem} would have thrown.
 */
export function safeParseItem(input: string): ParseResult<Item> {
  return safeRun(() => parseItem(input))
}

/**
 * Non-throwing variant of {@link parseList}.
 *
 * @param input The raw header value.
 * @returns A discriminated `ParseResult`.
 */
export function safeParseList(input: string): ParseResult<List> {
  return safeRun(() => parseList(input))
}

/**
 * Non-throwing variant of {@link parseDictionary}.
 *
 * @param input The raw header value.
 * @returns A discriminated `ParseResult`.
 */
export function safeParseDictionary(input: string): ParseResult<Dictionary> {
  return safeRun(() => parseDictionary(input))
}
