import { advance, type Cursor, expect as expectChar, parseFail, peek } from '@/parse/cursor'
import { DIGIT_ONE, DIGIT_ZERO, QUESTION_MARK } from '@/util/chars'

/**
 * Parses a Boolean at the cursor.
 *
 * Wire form: `?1` for true, `?0` for false. Any other digit after the leading
 * `?` is rejected.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.8 | RFC 9651 section 4.2.8}
 */
export function parseBoolean(cursor: Cursor): boolean {
  expectChar(cursor, QUESTION_MARK, "expected '?'")
  const charCode = peek(cursor)
  if (charCode === DIGIT_ONE) {
    advance(cursor)
    return true
  }
  if (charCode === DIGIT_ZERO) {
    advance(cursor)
    return false
  }
  parseFail(cursor, "expected '0' or '1'")
}
