import { ParseError } from '@/errors'
import { type Cursor, expect as expectChar } from '@/parse/cursor'
import { parseIntegerOrDecimal } from '@/parse/number'
import { AT_SIGN } from '@/util/chars'

/**
 * Parses a Date at the cursor.
 *
 * Wire form: `@` followed by a signed integer in the same range as Integer.
 * The body must not contain a decimal point; a Decimal-shaped body is
 * rejected.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.9 | RFC 9651 section 4.2.9}
 */
export function parseDate(cursor: Cursor): number {
  expectChar(cursor, AT_SIGN, "expected '@'")
  const numberStartOffset = cursor.offset
  const result = parseIntegerOrDecimal(cursor)
  if (result.type !== 'integer') {
    throw new ParseError('date body must be an integer', {
      offset: numberStartOffset,
      input: cursor.input,
    })
  }
  return result.value
}
