import { advance, type Cursor, parseFail, peek, skipOWS } from '@/parse/cursor'
import { parseInnerList } from '@/parse/inner-list'
import { parseItemInternal } from '@/parse/item'
import { parseKey } from '@/parse/key'
import { parseParameters } from '@/parse/parameters'
import type { Dictionary, ListEntry } from '@/types'
import { COMMA, EOF, EQUALS, LPAREN } from '@/util/chars'

/**
 * Parses a Dictionary at the cursor (internal helper).
 *
 * Each entry has a key and either an Item value, an Inner List value, or no
 * explicit value (which represents a Boolean `true`). For repeated keys the
 * value of the last occurrence wins, but the key keeps the position of its
 * first occurrence (`Map.set` preserves insertion order).
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.2 | RFC 9651 section 4.2.2}
 */
export function parseDictionaryInternal(cursor: Cursor): Dictionary {
  const entries = new Map<string, ListEntry>()
  if (peek(cursor) === EOF) {
    return entries
  }

  while (true) {
    const name = parseKey(cursor)
    entries.set(name, parseEntryValue(cursor))

    skipOWS(cursor)
    if (peek(cursor) === EOF) {
      return entries
    }
    if (peek(cursor) !== COMMA) {
      parseFail(cursor, "expected ',' or end of input")
    }

    advance(cursor) // consume the comma
    skipOWS(cursor)
    if (peek(cursor) === EOF) {
      parseFail(cursor, 'trailing comma in dictionary')
    }
  }
}

/**
 * Parses the right-hand side of a dictionary entry, including the optional
 * `=value` form. A bare key with no `=` is treated as a Boolean `true` Item
 * with any parameters that follow.
 */
function parseEntryValue(cursor: Cursor): ListEntry {
  if (peek(cursor) === EQUALS) {
    advance(cursor)
    if (peek(cursor) === LPAREN) {
      return parseInnerList(cursor)
    }
    return parseItemInternal(cursor)
  }
  const parameters = parseParameters(cursor)
  return {
    type: 'item',
    value: { type: 'boolean', value: true },
    parameters,
  }
}
