import { SerializeError } from '@/errors'
import { PERCENT, QUOTE, SP, TILDE } from '@/util/chars'

const HEX_DIGITS = '0123456789abcdef'

const HIGH_SURROGATE_MIN = 0xd800
const HIGH_SURROGATE_MAX = 0xdbff
const LOW_SURROGATE_MIN = 0xdc00
const LOW_SURROGATE_MAX = 0xdfff

function isHighSurrogate(charCode: number): boolean {
  return charCode >= HIGH_SURROGATE_MIN && charCode <= HIGH_SURROGATE_MAX
}

function isLowSurrogate(charCode: number): boolean {
  return charCode >= LOW_SURROGATE_MIN && charCode <= LOW_SURROGATE_MAX
}

/**
 * Serializes a Display String.
 *
 * Encodes the value as UTF-8 bytes, then percent-encodes any byte that is
 * not printable ASCII or that is one of the reserved characters `%` or `"`.
 * Lone surrogates are detected up front so we never silently produce
 * `U+FFFD` from `TextEncoder`.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.11 | RFC 9651 section 4.1.11}
 */
export function serializeDisplayString(value: string): string {
  validateNoLoneSurrogates(value)

  const bytes = new TextEncoder().encode(value)
  let output = '%"'
  for (let index = 0; index < bytes.length; index += 1) {
    const byte = bytes[index]!
    const isPrintableAscii = byte >= SP && byte <= TILDE
    const isReserved = byte === PERCENT || byte === QUOTE
    if (isPrintableAscii && !isReserved) {
      output += String.fromCharCode(byte)
    } else {
      output += '%' + HEX_DIGITS[byte >> 4]! + HEX_DIGITS[byte & 0x0f]!
    }
  }
  output += '"'
  return output
}

function validateNoLoneSurrogates(value: string): void {
  for (let index = 0; index < value.length; index += 1) {
    const charCode = value.charCodeAt(index)
    if (isHighSurrogate(charCode)) {
      const next = value.charCodeAt(index + 1)
      if (!isLowSurrogate(next)) {
        throw new SerializeError('display string contains a lone high surrogate', { code: 'display-string-encoding' })
      }
      index += 1 // skip the paired low surrogate
      continue
    }
    if (isLowSurrogate(charCode)) {
      throw new SerializeError('display string contains a lone low surrogate', {
        code: 'display-string-encoding',
      })
    }
  }
}
