import { SerializeError } from '@/errors'

const INTEGER_MAX = 999_999_999_999_999
const DECIMAL_INTEGER_MAX = 999_999_999_999

/**
 * Serializes an Integer.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.4 | RFC 9651 section 4.1.4}
 */
export function serializeInteger(value: number): string {
  if (!Number.isFinite(value) || !Number.isInteger(value)) {
    throw new SerializeError('integer must be a finite integer', {
      code: 'integer-range',
    })
  }
  if (value > INTEGER_MAX || value < -INTEGER_MAX) {
    throw new SerializeError('integer out of RFC 9651 range', {
      code: 'integer-range',
    })
  }
  return value.toString(10)
}

/**
 * Round half to even (banker's rounding) for an integer value.
 *
 * `n` is assumed to be of the form `k + 0.5` for some integer `k`, i.e. a
 * midpoint between two integers. If `n` is not exactly a midpoint the
 * behaviour falls back to `Math.round`.
 */
function roundHalfToEven(n: number): number {
  const floor = Math.floor(n)
  const diff = n - floor
  if (Math.abs(diff - 0.5) < 1e-10) {
    // Exactly halfway: round toward the nearest even integer.
    return floor % 2 === 0 ? floor : floor + 1
  }
  return Math.round(n)
}

/**
 * Serializes a Decimal.
 *
 * The integer part must not exceed 12 digits (`999999999999`). The fractional
 * part is rounded to at most 3 digits using round-half-to-even, the rounding
 * mode required by RFC 9651 section 4.1.5.
 *
 * @param value Any finite JS number within the spec's integer range.
 * @returns The canonical wire-form string, with at least one fractional digit
 *   (for example `0` becomes `"0.0"`).
 * @throws SerializeError when the value is not finite or the integer part
 *   exceeds 12 digits.
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.5 | RFC 9651 section 4.1.5}
 */
export function serializeDecimal(value: number): string {
  if (!Number.isFinite(value)) {
    throw new SerializeError('decimal must be finite', {
      code: 'decimal-precision',
    })
  }
  const rounded = roundHalfToEven(value * 1000) / 1000
  if (Math.abs(Math.trunc(rounded)) > DECIMAL_INTEGER_MAX) {
    throw new SerializeError('decimal integer part too long', {
      code: 'decimal-precision',
    })
  }
  let formatted = rounded.toFixed(3)
  while (formatted.endsWith('0') && !formatted.endsWith('.0')) {
    formatted = formatted.slice(0, -1)
  }
  return formatted
}
