import { advance, type Cursor, expect as expectChar, parseFail, peek } from '@/parse/cursor'
import { BACKSLASH, EOF, QUOTE, SP, TILDE } from '@/util/chars'

/**
 * Parses a String at the cursor and returns the decoded value (escape
 * sequences resolved).
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.5 | RFC 9651 section 4.2.5}
 */
export function parseString(cursor: Cursor): string {
  expectChar(cursor, QUOTE, "expected '\"'")

  let output = ''
  while (true) {
    const charCode = peek(cursor)
    if (charCode === EOF) {
      parseFail(cursor, 'unterminated string')
    }
    if (charCode === QUOTE) {
      advance(cursor)
      return output
    }
    if (charCode === BACKSLASH) {
      advance(cursor)
      const escaped = peek(cursor)
      if (escaped !== BACKSLASH && escaped !== QUOTE) {
        parseFail(cursor, 'invalid escape sequence')
      }
      output += String.fromCharCode(escaped)
      advance(cursor)
      continue
    }
    if (charCode < SP || charCode > TILDE) {
      parseFail(cursor, 'string contains non-printable character')
    }
    output += String.fromCharCode(charCode)
    advance(cursor)
  }
}
