import { serializeBoolean } from '@/serialize/boolean'
import { serializeByteSequence } from '@/serialize/byte-sequence'
import { serializeDate } from '@/serialize/date'
import { serializeDisplayString } from '@/serialize/display-string'
import { serializeDecimal, serializeInteger } from '@/serialize/number'
import { serializeString } from '@/serialize/string'
import { serializeToken } from '@/serialize/token'
import type { BareItem } from '@/types'

/**
 * Serializes a Bare Item by dispatching on its type.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.3.1 | RFC 9651 section 4.1.3.1}
 */
export function serializeBareItem(value: BareItem): string {
  switch (value.type) {
    case 'integer':
      return serializeInteger(value.value)
    case 'decimal':
      return serializeDecimal(value.value)
    case 'string':
      return serializeString(value.value)
    case 'token':
      return serializeToken(value.value)
    case 'byteSequence':
      return serializeByteSequence(value.value)
    case 'boolean':
      return serializeBoolean(value.value)
    case 'date':
      return serializeDate(value.value)
    case 'displayString':
      return serializeDisplayString(value.value)
  }
}
