import { advance, type Cursor, parseFail, peek, skipOWS } from '@/parse/cursor'
import { parseInnerList } from '@/parse/inner-list'
import { parseItemInternal } from '@/parse/item'
import type { List, ListEntry } from '@/types'
import { COMMA, EOF, LPAREN } from '@/util/chars'

/**
 * Parses a List at the cursor (internal helper).
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.1 | RFC 9651 section 4.2.1}
 */
export function parseListInternal(cursor: Cursor): List {
  const entries: ListEntry[] = []
  if (peek(cursor) === EOF) {
    return entries
  }

  while (true) {
    entries.push(parseListEntry(cursor))
    skipOWS(cursor)
    if (peek(cursor) === EOF) {
      return entries
    }
    if (peek(cursor) !== COMMA) {
      parseFail(cursor, "expected ',' or end of input")
    }

    advance(cursor) // consume the comma
    skipOWS(cursor)
    if (peek(cursor) === EOF) {
      parseFail(cursor, 'trailing comma in list')
    }
  }
}

/**
 * Parses a single list entry, choosing between Inner List and Item by
 * peeking the leading character.
 */
export function parseListEntry(cursor: Cursor): ListEntry {
  if (peek(cursor) === LPAREN) {
    return parseInnerList(cursor)
  }
  return parseItemInternal(cursor)
}
