import { ParseError } from '@/errors'
import { EOF, HTAB, SP } from '@/util/chars'

/**
 * Mutable cursor over an input string. Pass the same object through the call
 * chain. The parser advances `offset` as it consumes characters.
 */
export type Cursor = {
  input: string
  offset: number
}

/**
 * Returns the character code at the current cursor position, or {@link EOF}
 * (`-1`) when the cursor is past the end of the input.
 *
 * Using a sentinel rather than `undefined` keeps hot-loop callers free of
 * nullish checks.
 */
export function peek(cursor: Cursor): number {
  if (cursor.offset >= cursor.input.length) {
    return EOF
  }
  return cursor.input.charCodeAt(cursor.offset)
}

/**
 * Advances the cursor by one character.
 */
export function advance(cursor: Cursor): void {
  cursor.offset += 1
}

/**
 * Throws a {@link ParseError} carrying the cursor's current position and the
 * original input string for context. Returns `never`, so call sites do not
 * need a follow-up `return` or control-flow comment.
 */
export function parseFail(cursor: Cursor, message: string): never {
  throw new ParseError(message, {
    offset: cursor.offset,
    input: cursor.input,
  })
}

/**
 * Asserts that the character at the cursor is `charCode`, then advances.
 * Throws `ParseError` if the assertion fails or input is exhausted.
 */
export function expect(cursor: Cursor, charCode: number, message: string): void {
  if (peek(cursor) !== charCode) {
    parseFail(cursor, message)
  }
  advance(cursor)
}

/**
 * Skips runs of ASCII space. RFC 9651 section 4.2 mandates space only at the
 * top level, never tab or other whitespace.
 */
export function skipSP(cursor: Cursor): void {
  while (peek(cursor) === SP) {
    advance(cursor)
  }
}

/**
 * Skips Optional White Space (SP or HTAB) per RFC 7230 section 3.2.3. Used
 * around commas in List and Dictionary fields.
 */
export function skipOWS(cursor: Cursor): void {
  let charCode = peek(cursor)
  while (charCode === SP || charCode === HTAB) {
    advance(cursor)
    charCode = peek(cursor)
  }
}
