import { serializeItemInternal } from '@/serialize/item'
import { serializeParameters } from '@/serialize/parameters'
import type { InnerList } from '@/types'

/**
 * Serializes an Inner List.
 *
 * Members are separated by exactly one ASCII space. Inner list parameters
 * follow the closing parenthesis.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.1.1 | RFC 9651 section 4.1.1.1}
 */
export function serializeInnerList(innerList: InnerList): string {
  const body = innerList.value.map(serializeItemInternal).join(' ')
  return `(${body})${serializeParameters(innerList.parameters)}`
}
