/**
 * Stable identifiers for the failure categories surfaced by
 * {@link SerializeError.code}.
 *
 * The literal union lets consumers exhaustively switch on the code without
 * relying on the human-readable message.
 */
export type SerializeErrorCode =
  | 'integer-range'
  | 'decimal-precision'
  | 'string-characters'
  | 'token-grammar'
  | 'key-grammar'
  | 'base64-invalid'
  | 'display-string-encoding'

/**
 * Raised when an input string does not conform to RFC 9651.
 *
 * Thrown directly by the throwing parse functions ({@link parseItem},
 * {@link parseList}, {@link parseDictionary}) and surfaced through the
 * `error` field of `ParseResult` from the `safeParse*` variants.
 *
 * The {@link offset} property points at the character where the parser gave
 * up, which is useful for highlighting errors in tooling.
 */
export class ParseError extends Error {
  /** Zero-based character offset into the input where the error was detected. */
  readonly offset: number
  /** The input that was being parsed, retained for context in error messages. */
  readonly input: string

  constructor(message: string, options: { offset: number; input: string }) {
    super(message)
    this.name = 'ParseError'
    this.offset = options.offset
    this.input = options.input
  }
}

/**
 * Raised when a value cannot be represented per RFC 9651.
 *
 * Thrown by the serialize functions and by the construction helpers (so an
 * out-of-range Integer or a malformed Token surfaces at the call site rather
 * than later during serialization).
 *
 * The {@link code} property carries a {@link SerializeErrorCode} suitable
 * for programmatic handling without parsing the human-readable message.
 */
export class SerializeError extends Error {
  /** A stable identifier for the failure category. */
  readonly code: SerializeErrorCode

  constructor(message: string, options: { code: SerializeErrorCode }) {
    super(message)
    this.name = 'SerializeError'
    this.code = options.code
  }
}
