import { SerializeError } from '@/errors'
import { serializeDisplayString } from '@/serialize/display-string'
import { serializeKey } from '@/serialize/key'
import { serializeDecimal, serializeInteger } from '@/serialize/number'
import { serializeString } from '@/serialize/string'
import { serializeToken } from '@/serialize/token'
import type {
  BareItem,
  BooleanBareItem,
  ByteSequenceBareItem,
  DateBareItem,
  DecimalBareItem,
  DisplayStringBareItem,
  InnerList,
  IntegerBareItem,
  Item,
  Parameters,
  StringBareItem,
  TokenBareItem,
} from '@/types'
import { decodeBase64 } from '@/util/base64'

/**
 * Builds an Integer bare item.
 *
 * @param value A safe integer in the range `-(10**15 - 1)` to `10**15 - 1`.
 * @returns A tagged Integer.
 * @throws SerializeError when the value is not a finite integer or falls
 *   outside the spec's range.
 */
export function integer(value: number): IntegerBareItem {
  serializeInteger(value)
  return { type: 'integer', value }
}

/**
 * Builds a Decimal bare item.
 *
 * The integer part must fit in 12 digits. Fractional precision beyond 3
 * digits is preserved on the in-memory value, and {@link serializeDecimal}
 * rounds it on the way out using round-half-to-even.
 *
 * @param value A finite JS number.
 * @returns A tagged Decimal.
 * @throws SerializeError when the value is not finite or the integer part
 *   exceeds 12 digits.
 */
export function decimal(value: number): DecimalBareItem {
  serializeDecimal(value)
  return { type: 'decimal', value }
}

/**
 * Builds a String bare item.
 *
 * @param value Printable ASCII only (`0x20` to `0x7E`).
 * @returns A tagged String.
 * @throws SerializeError when the value contains non-printable or non-ASCII characters.
 */
export function string(value: string): StringBareItem {
  serializeString(value)
  return { type: 'string', value }
}

/**
 * Builds a Token bare item.
 *
 * @param value A non-empty string matching the Token grammar (RFC 9651
 *   section 3.3.4): the first character is `ALPHA` or `*`, subsequent
 *   characters are `tchar` plus `:` and `/`.
 * @returns A tagged Token.
 * @throws SerializeError when the value is empty or violates the grammar.
 */
export function token(value: string): TokenBareItem {
  serializeToken(value)
  return { type: 'token', value }
}

/**
 * Builds a Byte Sequence bare item.
 *
 * Two input shapes are accepted: a `Uint8Array` (kept by reference) or a
 * base64 string with the standard alphabet and required padding (decoded
 * eagerly so the resulting tagged value always carries raw bytes).
 *
 * @param value Raw bytes or a base64 string.
 * @returns A tagged Byte Sequence.
 * @throws SerializeError when a string input is not valid base64.
 */
export function byteSequence(value: Uint8Array | string): ByteSequenceBareItem {
  if (typeof value === 'string') {
    try {
      return { type: 'byteSequence', value: decodeBase64(value) }
    } catch (cause) {
      const message = cause instanceof Error ? cause.message : 'invalid base64'
      throw new SerializeError(message, { code: 'base64-invalid' })
    }
  }
  return { type: 'byteSequence', value }
}

/**
 * Builds a Boolean bare item.
 *
 * @param value Either `true` or `false`.
 * @returns A tagged Boolean.
 */
export function boolean(value: boolean): BooleanBareItem {
  return { type: 'boolean', value }
}

/**
 * Builds a Date bare item.
 *
 * A number is interpreted as integer seconds since the epoch. A `Date` is
 * floored to seconds toward negative infinity (matching wall-clock semantics
 * for sub-second components).
 *
 * @param value Integer seconds since epoch, or a `Date`.
 * @returns A tagged Date.
 * @throws SerializeError when the resulting seconds value is not an integer
 *   or is out of the Integer range.
 */
export function date(value: number | Date): DateBareItem {
  const seconds = typeof value === 'number' ? value : Math.floor(value.getTime() / 1000)
  serializeInteger(seconds)
  return { type: 'date', value: seconds }
}

/**
 * Builds a Display String bare item.
 *
 * The value can be any well-formed Unicode string. {@link serializeDisplayString}
 * percent-encodes UTF-8 bytes that are not printable ASCII when the value is
 * written to the wire.
 *
 * @param value A well-formed Unicode string.
 * @returns A tagged Display String.
 * @throws SerializeError when the value contains a lone surrogate.
 */
export function displayString(value: string): DisplayStringBareItem {
  serializeDisplayString(value)
  return { type: 'displayString', value }
}

/**
 * Wraps a bare item into a full Item with optional parameters.
 *
 * Re-exported from the package root as `itemConstruct` to avoid colliding
 * with {@link parseItem} and the schema-layer `item` helper.
 *
 * @param value The bare item to wrap.
 * @param parametersInput Optional iterable of `[name, BareItem]` entries.
 * @returns An Item with the supplied value and parameters.
 *
 * @example
 * ```ts
 * import { itemConstruct, integer, boolean } from "http-structured-fields";
 * const priority = itemConstruct(integer(1), [["i", boolean(true)]]);
 * ```
 */
export function item(value: BareItem, parametersInput?: Iterable<readonly [string, BareItem]>): Item {
  return { type: 'item', value, parameters: parameters(parametersInput) }
}

/**
 * Builds an Inner List from a sequence of Items and optional Parameters.
 *
 * @param values The items that will appear inside the parentheses.
 * @param parametersInput Optional iterable of `[name, BareItem]` entries.
 * @returns An InnerList.
 */
export function innerList(values: Iterable<Item>, parametersInput?: Iterable<readonly [string, BareItem]>): InnerList {
  return {
    type: 'innerList',
    value: Array.from(values),
    parameters: parameters(parametersInput),
  }
}

/**
 * Builds a Parameters map from an iterable of entries.
 *
 * Each key is validated against the Key grammar (RFC 9651 section 3.1.2)
 * eagerly, so the caller sees a clear error at construction time instead of
 * a deferred error during serialization.
 *
 * @param entries Optional iterable of `[name, BareItem]` entries.
 * @returns A new Parameters map preserving the iteration order of the input.
 * @throws SerializeError when any key fails grammar validation.
 */
export function parameters(entries?: Iterable<readonly [string, BareItem]>): Parameters {
  const map = new Map<string, BareItem>()
  if (!entries) {
    return map
  }
  for (const [name, value] of entries) {
    serializeKey(name)
    map.set(name, value)
  }
  return map
}
