import { advance, type Cursor, parseFail, peek } from '@/parse/cursor'
import { isKeyChar, isKeyStart } from '@/util/ascii'

/**
 * Parses a Key (parameter name or dictionary key) at the cursor.
 *
 * The Key grammar requires the first character to be a lowercase letter or
 * `*`, with subsequent characters drawn from `lcalpha`, digits, `_`, `-`,
 * `.`, or `*`. Parsing stops at the first character that does not match.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.2.3.3 | RFC 9651 section 4.2.3.3}
 */
export function parseKey(cursor: Cursor): string {
  if (!isKeyStart(peek(cursor))) {
    parseFail(cursor, 'expected key start')
  }

  const startOffset = cursor.offset
  advance(cursor) // consume the validated start character
  while (isKeyChar(peek(cursor))) {
    advance(cursor)
  }
  return cursor.input.slice(startOffset, cursor.offset)
}
