import { SerializeError } from '@/errors'
import { isKeyChar, isKeyStart } from '@/util/ascii'

/**
 * Serializes a Key.
 *
 * @see {@link https://www.rfc-editor.org/rfc/rfc9651#section-4.1.1.3 | RFC 9651 section 4.1.1.3}
 */
export function serializeKey(value: string): string {
  if (value.length === 0) {
    throw new SerializeError('key must not be empty', { code: 'key-grammar' })
  }
  if (!isKeyStart(value.charCodeAt(0))) {
    throw new SerializeError("key must start with lowercase letter or '*'", {
      code: 'key-grammar',
    })
  }
  for (let index = 1; index < value.length; index += 1) {
    if (!isKeyChar(value.charCodeAt(index))) {
      throw new SerializeError('key contains invalid character', {
        code: 'key-grammar',
      })
    }
  }
  return value
}
